/* An XOR mask, the beam pseudo-elements on an offset path and a registered angle fallback. */
@property --kg-beam-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@layer kg.components {
  .kg-border-beam {
    --_size: var(--kg-beam-size, 80px);
    --_duration: var(--kg-beam-duration, 6s);
    --_delay: var(--kg-beam-delay, 0s);

    /* Two masks XOR'd leave only the edge band, so the beam never crosses the content. */
    -webkit-mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask:
      linear-gradient(#000 0 0) content-box exclude,
      linear-gradient(#000 0 0);

    /* The beam rides the container's own outline at constant speed, corners included. */
    &::after {
      content: "";
      position: absolute;
      width: var(--_size);
      aspect-ratio: 1;
      offset-path: rect(0 auto auto 0 round var(--_path-radius, 0px));
      offset-anchor: 90% 50%;
      background: linear-gradient(to left, var(--_from), var(--_to), transparent);
      animation: kg-beam-travel var(--_duration) linear var(--_delay) infinite;
    }

    &[data-reverse]::after {
      offset-anchor: 10% 50%;
      background: linear-gradient(to right, var(--_from), var(--_to), transparent);
      animation-direction: reverse;
    }

    &[data-paused]::after,
    &[data-paused]::before {
      animation-play-state: paused;
    }
  }

  @keyframes kg-beam-travel {
    from {
      offset-distance: 0%;
    }
    to {
      offset-distance: 100%;
    }
  }

  @keyframes kg-beam-spin {
    to {
      --kg-beam-angle: 360deg;
    }
  }

  /* Without offset-path shapes, sweep a conic gradient around the edge instead. */
  @supports not (offset-path: rect(0 auto auto 0)) {
    .kg-border-beam {
      &::after {
        display: none;
      }

      &::before {
        content: "";
        position: absolute;
        inset: 0;
        background: conic-gradient(
          from var(--kg-beam-angle),
          transparent 0turn,
          transparent 0.72turn,
          var(--_to) 0.92turn,
          var(--_from) 1turn
        );
        animation: kg-beam-spin var(--_duration) linear var(--_delay) infinite;
      }

      &[data-reverse]::before {
        background: conic-gradient(
          from var(--kg-beam-angle),
          var(--_from) 0turn,
          var(--_to) 0.08turn,
          transparent 0.28turn,
          transparent 1turn
        );
        animation-direction: reverse;
      }
    }
  }

  /* Reduced motion: a still gradient edge in the same colours. */
  @media (prefers-reduced-motion: reduce) {
    .kg-border-beam {
      &::after {
        display: none;
      }

      &::before {
        content: "";
        position: absolute;
        inset: 0;
        animation: none;
        background: linear-gradient(135deg, var(--_from), transparent 35%, transparent 65%, var(--_to));
      }
    }
  }

  [data-kg-motion="reduce"] .kg-border-beam {
    &::after {
      display: none;
    }

    &::before {
      content: "";
      position: absolute;
      inset: 0;
      animation: none;
      background: linear-gradient(135deg, var(--_from), transparent 35%, transparent 65%, var(--_to));
    }
  }
}

"use client"

import { type CSSProperties, forwardRef, type HTMLAttributes, useRef } from "react"
import { useIsomorphicLayoutEffect } from "../lib/hooks/use-isomorphic-layout-effect"
import { useComposedRefs } from "../lib/utils/compose-refs"
import { cx } from "../lib/utils/cx"
import { usePlayback } from "../marquee/use-playback"

export interface BorderBeamProps extends HTMLAttributes<HTMLDivElement> {
  /** Length of the beam, in px. */
  size?: number
  /** Seconds per lap. */
  duration?: number
  /** Phase offset in seconds. Give two beams `delay={duration / 2}` to have them chase. */
  delay?: number
  /** Colour at the head of the beam. Defaults to the ink. */
  colorFrom?: string
  /** Colour the tail fades through. Defaults to the peach paper. */
  colorTo?: string
  /** Thickness of the lit edge, in px. */
  borderWidth?: number
  reverse?: boolean
}

/**
 * A beam of ink that travels around the border of its nearest positioned ancestor. Place it as
 * the last child of any `position: relative` container; it inherits the container's radius.
 */
export const BorderBeam = forwardRef<HTMLDivElement, BorderBeamProps>(
  (
    {
      size = 80,
      duration = 6,
      delay = 0,
      colorFrom,
      colorTo,
      borderWidth = 1.5,
      reverse = false,
      className,
      style,
      ...props
    },
    forwardedRef,
  ) => {
    const local = useRef<HTMLDivElement>(null)
    const ref = useComposedRefs(local, forwardedRef)
    const playing = usePlayback(local)

    // offset-path cannot inherit a radius, so copy the container's corner into the path.
    useIsomorphicLayoutEffect(() => {
      const node = local.current
      if (!node) return
      const sync = () => {
        const corner = getComputedStyle(node).borderTopLeftRadius
        node.style.setProperty("--_path-radius", corner.split(" ")[0] || "0px")
      }
      sync()
      const observer = new ResizeObserver(sync)
      observer.observe(node)
      return () => observer.disconnect()
    }, [])

    return (
      <div
        ref={ref}
        aria-hidden="true"
        className={cx(
          "kg-border-beam pointer-events-none absolute inset-0 rounded-[inherit] p-[var(--kg-beam-width,1.5px)] [--_from:var(--kg-beam-from,var(--kg-ink))] [--_to:var(--kg-beam-to,var(--kg-paper-peach))]",
          className,
        )}
        data-reverse={reverse || undefined}
        data-paused={!playing || undefined}
        style={
          {
            "--kg-beam-size": `${size}px`,
            "--kg-beam-duration": `${duration}s`,
            "--kg-beam-delay": `${-delay}s`,
            "--kg-beam-width": `${borderWidth}px`,
            ...(colorFrom ? { "--kg-beam-from": colorFrom } : null),
            ...(colorTo ? { "--kg-beam-to": colorTo } : null),
            ...style,
          } as CSSProperties
        }
        {...props}
      />
    )
  },
)

BorderBeam.displayName = "BorderBeam"
